using namespace std;
int h[1005]={0};  
queue<int>tjc; 
int main(){
    int m,n;
    cin>>m>>n;
    int cnt=0; 
    while(n--){
    	int en;
    	cin>>en;     
    	if(h[en]==0){  
    		++cnt;
    		tjc.push(en);  
    		h[en]=1;   
    		while(tjc.size()>m){  
    			h[tjc.front()]=0; 
    			tjc.pop(); 
			}
		}
	}
	cout<<cnt;
return 0;
