#include <vector>
#include <iostream> 
#include <algorithm>

int main() {
	int m, n, t, ans = 0;
	std::cin >> m >> n;
	std::vector<int> v;  
	while (std::cin >> t) {
		if (std::find(v.begin(), v.end(), t) == v.end()) {  
			v.push_back(t);  
			++ans;
		}
		if (v.size() > m)  
			v.erase(v.begin());  
	}
	std::cout << ans << std::endl;
}
